(()=>{
 const dialog=$('#action-dialog'),form=$('#action-form');let source=null,filter='open',busy=false;
 const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
 function renderActions(){const list=mails.flatMap(mail=>(mail.actions||[]).map(task=>({mail,task}))).filter(({task})=>filter==='done'?task.done:!task.done&&(filter!=='due'||task.due&&task.due<=today())).sort((a,b)=>(a.task.due||'9999').localeCompare(b.task.due||'9999'));$('#action-list').innerHTML=list.length?list.map(({mail,task})=>`<article class="action-item"><div><strong>${escape(task.title)}</strong><span>${task.due?escape(task.due)+(task.due<=today()&&!task.done?' · Due now':''):'No due date'}</span><small>From ${escape(mail.from)} · ${escape(mail.subject)}</small></div><div><button data-action-source="${escape(mail.id)}">Open email</button><button data-action-toggle="${escape(task.id)}">${task.done?'Reopen':'Done'}</button><button data-action-remove="${escape(task.id)}" aria-label="Remove task ${escape(task.title)}">×</button></div></article>`).join(''):'<p class="widget-hint">Nothing here. Open an email and choose “Turn into a task” to give it a next step.</p>';document.querySelectorAll('[data-actions-filter]').forEach(b=>b.classList.toggle('selected',b.dataset.actionsFilter===filter))}
 $('#open-actions').onclick=()=>{if(document.querySelector('dialog[open]'))return;form.hidden=true;renderActions();dialog.showModal()};
 $('#make-action').onclick=()=>{if(!current)return;source=current.id;$('#action-title').value=current.subject||'';$('#action-due').value='';$('#reader').close();form.hidden=false;renderActions();dialog.showModal()};
 form.onsubmit=async e=>{e.preventDefault();if(busy)return;const mail=mails.find(m=>m.id===source),title=$('#action-title').value.trim(),due=$('#action-due').value;if(!mail||!title||title.length>200)return;busy=true;$('#action-add').disabled=true;rememberChange(mail);mail.actions??=[];mail.actions.push({id:crypto.randomUUID(),title,due,done:false});try{if(await save()){form.hidden=true;toast('Task saved with its original email.')}renderActions();render()}finally{busy=false;$('#action-add').disabled=false}};
 dialog.addEventListener('click',async e=>{const f=e.target.closest('[data-actions-filter]');if(f){filter=f.dataset.actionsFilter;renderActions();return}const open=e.target.closest('[data-action-source]');if(open){dialog.close();openMessage(open.dataset.actionSource);return}const toggle=e.target.closest('[data-action-toggle]'),remove=e.target.closest('[data-action-remove]');if(!toggle&&!remove)return;const id=toggle?.dataset.actionToggle||remove.dataset.actionRemove,mail=mails.find(m=>m.actions?.some(t=>t.id===id));if(!mail)return;rememberChange(mail);if(remove)mail.actions=mail.actions.filter(t=>t.id!==id);else{const task=mail.actions.find(t=>t.id===id);task.done=!task.done}await save();renderActions();render();toast('Task updated. Use Undo last change to restore it.')});
 window.addEventListener('mail-account-changed',()=>{source=null;dialog.close();$('#action-title').value='';$('#action-due').value=''})
})();
